<?php
namespace App\Http\Controllers;
use App\Models\{Review,Service,Activity};
use App\Http\Requests\ReviewRequest;
use App\Services\PublicSubmissions;
use Illuminate\Http\Request;
use Illuminate\Validation\ValidationException;
class ReviewController extends Controller {
 public function submit(ReviewRequest $r,PublicSubmissions $s){try{$s->review($r,$r->validated());}catch(ValidationException $e){return $r->expectsJson()?response()->json(['errors'=>$e->errors()],422):back()->withErrors($e->errors());}return $r->expectsJson()?response()->json(['message'=>'Thank you. Your review is awaiting moderation.'],201):redirect()->route('reviews')->with('success','Thank you. Your review is awaiting moderation.');}
 public function index(Request $r){$q=Review::with('service');if($r->status==='trash')$q->onlyTrashed();elseif(in_array($r->status,['pending','approved','rejected','spam'],true))$q->where('status',$r->status);if($r->filled('q'))$q->where('original_text','like','%'.mb_substr($r->q,0,100).'%');if($r->filled('service_id'))$q->where('service_id',$r->integer('service_id'));if(in_array($r->source,['website','admin'],true))$q->where('source',$r->source);if($r->filled('rating'))$q->where('rating',$r->integer('rating'));\App\Services\DateFilters::apply($q,$r,'created_at');return view('centre.index',['title'=>'Reviews','kind'=>'reviews-admin','items'=>$q->latest()->paginate(15)->withQueryString()]);}
 public function create(){return view('centre.review-form',['review'=>new Review(['status'=>'pending','anonymous'=>true]),'services'=>Service::orderBy('name')->get()]);}
 public function edit(Review $review){return view('centre.review-form',compact('review')+['services'=>Service::orderBy('name')->get()]);}
 public function show(Review $review){return $this->edit($review);}
 public function store(Request $r){return $this->save($r,new Review);}
 public function update(Request $r,Review $review){return $this->save($r,$review);}
 private function save(Request $r,Review $review){$d=$r->validate(['display_name'=>['nullable','string','max:120'],'anonymous'=>['required','boolean'],'email'=>['required','email','max:254'],'rating'=>['nullable','integer','between:1,5'],'original_text'=>[$review->exists?'prohibited':'required','string','max:3000'],'public_text'=>['nullable','string','max:3000'],'service_id'=>['nullable','exists:services,id'],'publication_consent'=>['required','boolean'],'consented_at'=>['nullable','date_format:Y-m-d\TH:i'],'status'=>['required','in:pending,approved,rejected,spam'],'featured'=>['nullable','boolean'],'display_order'=>['required','integer','between:0,9999'],'moderation_notes'=>['nullable','string','max:4000']]);foreach(['original_text','public_text'] as $k)if(isset($d[$k])&&$d[$k]!==strip_tags($d[$k]))throw ValidationException::withMessages([$k=>'Use plain text.']);if(!$d['anonymous']&&!trim($d['display_name']??''))throw ValidationException::withMessages(['display_name'=>'Provide a name or choose anonymous.']);$d['consented_at']=empty($d['consented_at'])?null:\Illuminate\Support\Carbon::createFromFormat('Y-m-d\TH:i',$d['consented_at'],'Asia/Kolkata')->utc();if($d['status']==='approved'&&(!$d['publication_consent']||!$d['consented_at']))throw ValidationException::withMessages(['publication_consent'=>'Approved publication consent and its actual date are required.']);if(!$review->exists){$d['submission_key']=(string)\Illuminate\Support\Str::uuid();$d['duplicate_key']=hash('sha256',random_bytes(32));$d['source']='admin';$d['consent_version']=app(\App\Services\WebsiteSettings::class)->get('review_consent_version');}$d['featured']=(bool)($d['featured']??false);$d['moderator_id']=$r->user()->id;$d['moderated_at']=now();\Illuminate\Support\Facades\DB::transaction(function()use($review,$d){\Illuminate\Support\Facades\DB::table('staff_locks')->where('id',1)->lockForUpdate()->first();if($d['status']==='approved')app(\App\Services\FeedbackPublication::class)->check(($d['public_text']??null)?:($review->original_text??$d['original_text']),'review',$review->id);$review->fill($d)->save();});Activity::record('Review moderated','Review #'.$review->id);return redirect()->route('reviews-admin.edit',$review)->with('success','Review saved. Only approved, consented reviews are public.');}
 public function destroy(Review $review){$review->previous_status=$review->status;$review->save();$review->delete();return redirect()->route('reviews-admin.index')->with('success','Review archived.');}
 public function restore(int $review){$r=Review::onlyTrashed()->findOrFail($review);$r->status='pending';$r->featured=false;$r->restore();$r->save();return back()->with('success','Review restored pending moderation.');}
}
